 local spine=make("Frame",{Name="BookSpine",Position=UDim2.fromScale(.498,.065),Size=UDim2.fromScale(.004,.87),BackgroundColor3=Color3.fromRGB(150,111,68),BorderSizePixel=0,ZIndex=42},book)
